----TODO  因为轮盘旋转是个假动画  所以在取数据的时候  用当前item的index减去当前次数 就可以获得对应的正确数据
--- 比数第一轮 第二次  这时候应该是2在主位置 对应数据应该是  1+2-1  2+2-1 3+2-1
function GachaponStepDiscTypeCell:RefreshShow(data, isUnLock, curStep, isMaxTurn)
    self.data = data
    local count = table.count(self.data.consumeInfo)
    for i = 1, count do
        local item = self["DiscGoodsNode"..i]
        if not isNull(item) then
            local env = CfUtils.GetLuaScr(item.gameObject,NodePath)
            if isNotNull(env) then
                env:SetCurIndex(i, isUnLock)
                local index = i + curStep - 1
                if index > count then
                    index = index - count
                end
                env:RefreshShow(self.data.consumeInfo[index], curStep, index, isMaxTurn)
            end
        end
    end
end


function GachaponStepDiscTypeCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return GachaponStepDiscTypeCell